window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-37c6c5fc9b7bc10f"]={"versions": [{"id": "FIG-37c6c5fc9b7bc10f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Software-Components (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.\n</li><li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.\n</li></ul>\n</li><li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).\n</li><li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).\n</li><li><code>CrsCtlAndAcc</code> (Cruise Control &amp; Adaptive Cruise Control).\n</li><li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).\n</li></ul>\n</li><li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong>\n<ul class=\"fig-list\"><li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.\n</li><li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.\n</li><li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).\n</li><li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.\n</li><li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).\n</li><li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</h5>\n<ul class=\"fig-list\"><li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.\n</li><li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.\n</li><li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.\n</li><li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.\n</li><li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.\n</li><li><strong>Kardinalitäten:</strong> 1:n-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); n:1-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.\n</li><li><strong>Kopplungen:</strong>\n<ul class=\"fig-list\"><li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.\n</li><li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sollwert-Erfassung &amp; Vorkonditionierung (Asynchron / Periodisch):</strong>\n<ul class=\"fig-list\"><li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.\n</li></ul>\n</li><li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong>\n<ul class=\"fig-list\"><li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung &gt; Notausweich-Assistenz &gt; Komfort-Assistenz).\n</li><li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.\n</li></ul>\n</li><li><strong>Kinematische Transformation &amp; Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong>\n<ul class=\"fig-list\"><li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).\n</li><li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).\n</li></ul>\n</li><li><strong>Low-Level-Arbitrierung &amp; Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong>\n<ul class=\"fig-list\"><li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).\n</li><li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).\n</li></ul>\n</li><li><strong>Aktuator-Ansteuerung &amp; Feedback (Synchrone Reglerschleife):</strong>\n<ul class=\"fig-list\"><li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).\n</li><li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> → <code>SAC</code> → <code>Esc</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong>\n<ul class=\"fig-list\"><li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.\n</li><li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.\n</li></ul>\n</li><li><strong>RTE- und Task-Design:</strong>\n<ul class=\"fig-list\"><li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks (t_cycle = 5\\,ms … 10\\,ms).\n</li><li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung (t_cycle ≤ 1\\,ms … 2\\,ms), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.\n</li></ul>\n</li><li><strong>Signalintegrität &amp; ASIL-Allokation:</strong>\n<ul class=\"fig-list\"><li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.\n</li><li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-c73af67f5ddf6043", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Software-Components (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.\n</li><li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.\n</li></ul>\n</li><li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).\n</li><li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).\n</li><li><code>CrsCtlAndAcc</code> (Cruise Control &amp; Adaptive Cruise Control).\n</li><li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).\n</li></ul>\n</li><li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong>\n<ul class=\"fig-list\"><li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.\n</li><li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.\n</li><li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).\n</li><li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.\n</li><li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).\n</li><li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</h5>\n<ul class=\"fig-list\"><li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.\n</li><li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.\n</li><li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.\n</li><li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.\n</li><li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.\n</li><li><strong>Kardinalitäten:</strong> 1:n-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); n:1-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.\n</li><li><strong>Kopplungen:</strong>\n<ul class=\"fig-list\"><li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.\n</li><li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sollwert-Erfassung &amp; Vorkonditionierung (Asynchron / Periodisch):</strong>\n<ul class=\"fig-list\"><li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.\n</li></ul>\n</li><li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong>\n<ul class=\"fig-list\"><li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung &gt; Notausweich-Assistenz &gt; Komfort-Assistenz).\n</li><li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.\n</li></ul>\n</li><li><strong>Kinematische Transformation &amp; Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong>\n<ul class=\"fig-list\"><li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).\n</li><li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).\n</li></ul>\n</li><li><strong>Low-Level-Arbitrierung &amp; Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong>\n<ul class=\"fig-list\"><li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).\n</li><li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).\n</li></ul>\n</li><li><strong>Aktuator-Ansteuerung &amp; Feedback (Synchrone Reglerschleife):</strong>\n<ul class=\"fig-list\"><li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).\n</li><li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> → <code>SAC</code> → <code>Esc</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong>\n<ul class=\"fig-list\"><li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.\n</li><li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.\n</li></ul>\n</li><li><strong>RTE- und Task-Design:</strong>\n<ul class=\"fig-list\"><li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks (t_cycle = 5\\,ms … 10\\,ms).\n</li><li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung (t_cycle ≤ 1\\,ms … 2\\,ms), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.\n</li></ul>\n</li><li><strong>Signalintegrität &amp; ASIL-Allokation:</strong>\n<ul class=\"fig-list\"><li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.\n</li><li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-628d70dbcd1152a8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Software-Components (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.\n</li><li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.\n</li></ul>\n</li><li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).\n</li><li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).\n</li><li><code>CrsCtlAndAcc</code> (Cruise Control &amp; Adaptive Cruise Control).\n</li><li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).\n</li></ul>\n</li><li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong>\n<ul class=\"fig-list\"><li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.\n</li><li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.\n</li><li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).\n</li><li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.\n</li><li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).\n</li><li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</h5>\n<ul class=\"fig-list\"><li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.\n</li><li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.\n</li><li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.\n</li><li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.\n</li><li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.\n</li><li><strong>Kardinalitäten:</strong> 1:n-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); n:1-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.\n</li><li><strong>Kopplungen:</strong>\n<ul class=\"fig-list\"><li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.\n</li><li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sollwert-Erfassung &amp; Vorkonditionierung (Asynchron / Periodisch):</strong>\n<ul class=\"fig-list\"><li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.\n</li></ul>\n</li><li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong>\n<ul class=\"fig-list\"><li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung &gt; Notausweich-Assistenz &gt; Komfort-Assistenz).\n</li><li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.\n</li></ul>\n</li><li><strong>Kinematische Transformation &amp; Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong>\n<ul class=\"fig-list\"><li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).\n</li><li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).\n</li></ul>\n</li><li><strong>Low-Level-Arbitrierung &amp; Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong>\n<ul class=\"fig-list\"><li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).\n</li><li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).\n</li></ul>\n</li><li><strong>Aktuator-Ansteuerung &amp; Feedback (Synchrone Reglerschleife):</strong>\n<ul class=\"fig-list\"><li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).\n</li><li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> → <code>SAC</code> → <code>Esc</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong>\n<ul class=\"fig-list\"><li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.\n</li><li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.\n</li></ul>\n</li><li><strong>RTE- und Task-Design:</strong>\n<ul class=\"fig-list\"><li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks (t_cycle = 5\\,ms … 10\\,ms).\n</li><li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung (t_cycle ≤ 1\\,ms … 2\\,ms), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.\n</li></ul>\n</li><li><strong>Signalintegrität &amp; ASIL-Allokation:</strong>\n<ul class=\"fig-list\"><li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.\n</li><li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-ce6167db30a6a08b", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Software-Components (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.\n</li><li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.\n</li></ul>\n</li><li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).\n</li><li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).\n</li><li><code>CrsCtlAndAcc</code> (Cruise Control &amp; Adaptive Cruise Control).\n</li><li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).\n</li></ul>\n</li><li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong>\n<ul class=\"fig-list\"><li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.\n</li><li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.\n</li><li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).\n</li><li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.\n</li><li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).\n</li><li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</h5>\n<ul class=\"fig-list\"><li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.\n</li><li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.\n</li><li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.\n</li><li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.\n</li><li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.\n</li><li><strong>Kardinalitäten:</strong> 1:n-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); n:1-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.\n</li><li><strong>Kopplungen:</strong>\n<ul class=\"fig-list\"><li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.\n</li><li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sollwert-Erfassung &amp; Vorkonditionierung (Asynchron / Periodisch):</strong>\n<ul class=\"fig-list\"><li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.\n</li></ul>\n</li><li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong>\n<ul class=\"fig-list\"><li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung &gt; Notausweich-Assistenz &gt; Komfort-Assistenz).\n</li><li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.\n</li></ul>\n</li><li><strong>Kinematische Transformation &amp; Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong>\n<ul class=\"fig-list\"><li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).\n</li><li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).\n</li></ul>\n</li><li><strong>Low-Level-Arbitrierung &amp; Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong>\n<ul class=\"fig-list\"><li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).\n</li><li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).\n</li></ul>\n</li><li><strong>Aktuator-Ansteuerung &amp; Feedback (Synchrone Reglerschleife):</strong>\n<ul class=\"fig-list\"><li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).\n</li><li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> → <code>SAC</code> → <code>Esc</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong>\n<ul class=\"fig-list\"><li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.\n</li><li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.\n</li></ul>\n</li><li><strong>RTE- und Task-Design:</strong>\n<ul class=\"fig-list\"><li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks (t_cycle = 5\\,ms … 10\\,ms).\n</li><li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung (t_cycle ≤ 1\\,ms … 2\\,ms), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.\n</li></ul>\n</li><li><strong>Signalintegrität &amp; ASIL-Allokation:</strong>\n<ul class=\"fig-list\"><li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.\n</li><li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-cc1fe776cb87f790", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Software-Components (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.\n</li><li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.\n</li></ul>\n</li><li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).\n</li><li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).\n</li><li><code>CrsCtlAndAcc</code> (Cruise Control &amp; Adaptive Cruise Control).\n</li><li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).\n</li></ul>\n</li><li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong>\n<ul class=\"fig-list\"><li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.\n</li><li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.\n</li><li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).\n</li><li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.\n</li><li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).\n</li><li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</h5>\n<ul class=\"fig-list\"><li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.\n</li><li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.\n</li><li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.\n</li><li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.\n</li><li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.\n</li><li><strong>Kardinalitäten:</strong> 1:n-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); n:1-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.\n</li><li><strong>Kopplungen:</strong>\n<ul class=\"fig-list\"><li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.\n</li><li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sollwert-Erfassung &amp; Vorkonditionierung (Asynchron / Periodisch):</strong>\n<ul class=\"fig-list\"><li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.\n</li></ul>\n</li><li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong>\n<ul class=\"fig-list\"><li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung &gt; Notausweich-Assistenz &gt; Komfort-Assistenz).\n</li><li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.\n</li></ul>\n</li><li><strong>Kinematische Transformation &amp; Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong>\n<ul class=\"fig-list\"><li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).\n</li><li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).\n</li></ul>\n</li><li><strong>Low-Level-Arbitrierung &amp; Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong>\n<ul class=\"fig-list\"><li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).\n</li><li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).\n</li></ul>\n</li><li><strong>Aktuator-Ansteuerung &amp; Feedback (Synchrone Reglerschleife):</strong>\n<ul class=\"fig-list\"><li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).\n</li><li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> → <code>SAC</code> → <code>Esc</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong>\n<ul class=\"fig-list\"><li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.\n</li><li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.\n</li></ul>\n</li><li><strong>RTE- und Task-Design:</strong>\n<ul class=\"fig-list\"><li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks (t_cycle = 5\\,ms … 10\\,ms).\n</li><li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung (t_cycle ≤ 1\\,ms … 2\\,ms), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.\n</li></ul>\n</li><li><strong>Signalintegrität &amp; ASIL-Allokation:</strong>\n<ul class=\"fig-list\"><li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.\n</li><li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2f0f777aaed749c6", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Software-Components (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.\n</li><li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.\n</li></ul>\n</li><li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).\n</li><li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).\n</li><li><code>CrsCtlAndAcc</code> (Cruise Control &amp; Adaptive Cruise Control).\n</li><li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).\n</li></ul>\n</li><li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong>\n<ul class=\"fig-list\"><li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.\n</li><li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.\n</li><li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).\n</li><li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.\n</li><li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).\n</li><li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</h5>\n<ul class=\"fig-list\"><li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.\n</li><li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.\n</li><li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.\n</li><li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.\n</li><li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.\n</li><li><strong>Kardinalitäten:</strong> 1:n-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); n:1-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.\n</li><li><strong>Kopplungen:</strong>\n<ul class=\"fig-list\"><li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.\n</li><li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sollwert-Erfassung &amp; Vorkonditionierung (Asynchron / Periodisch):</strong>\n<ul class=\"fig-list\"><li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.\n</li></ul>\n</li><li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong>\n<ul class=\"fig-list\"><li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung &gt; Notausweich-Assistenz &gt; Komfort-Assistenz).\n</li><li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.\n</li></ul>\n</li><li><strong>Kinematische Transformation &amp; Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong>\n<ul class=\"fig-list\"><li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).\n</li><li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).\n</li></ul>\n</li><li><strong>Low-Level-Arbitrierung &amp; Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong>\n<ul class=\"fig-list\"><li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).\n</li><li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).\n</li></ul>\n</li><li><strong>Aktuator-Ansteuerung &amp; Feedback (Synchrone Reglerschleife):</strong>\n<ul class=\"fig-list\"><li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).\n</li><li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> → <code>SAC</code> → <code>Esc</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong>\n<ul class=\"fig-list\"><li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.\n</li><li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.\n</li></ul>\n</li><li><strong>RTE- und Task-Design:</strong>\n<ul class=\"fig-list\"><li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks (t_cycle = 5\\,ms … 10\\,ms).\n</li><li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung (t_cycle ≤ 1\\,ms … 2\\,ms), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.\n</li></ul>\n</li><li><strong>Signalintegrität &amp; ASIL-Allokation:</strong>\n<ul class=\"fig-list\"><li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.\n</li><li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.\n</li></ul>\n</li></ul>"}, {"id": "FIG-8f3cb66c199fc31a", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Informelles AUTOSAR VFB-Komponentendiagramm / Funktionsarchitektur-Blockschaltbild (Darstellung einer übergeordneten <code>CompositionSwComponentType</code> bzw. Funktionsdomäne und deren Dekomposition in <code>AtomicSwComponentType</code>-Bausteine und herstellerspezifische Algorithmenkerne).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der funktionalen Dekomposition des Chassis-Subsystems <em>Steering</em> (<code>Steer SW-C</code>) gemäß <code>AUTOSAR_EXP_AIChassis</code> (R4.0.3). Es definiert die Schnittstellengrenzen zwischen normierten AUTOSAR Application Interfaces (Inter-SW-C VFB-Kommunikation) und proprietären Regelungs-/Aktuatorfunktionen der Tier-1/OEM-Ebene.\n</li><li><strong>Funktionale Einordnung:</strong> Vertikale Entkopplung von High-Level-Fahrdynamikfunktionen (ADAS, ESP) und Low-Level-Aktuatorik (EPS, AFS, Allradlenkung). Dient als Referenzarchitektur für Arbitrierung, kinematische Koordinatenwandlung (Ritzel- zu Radwinkel) sowie Drehmoment- und Winkelüberlagerung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Software-Components (SW-Cs)</h5>\n<ul class=\"fig-list\"><li><strong>Übergeordnete Lenkungsfunktions-SW-Cs (<code>Higher steering function SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>VehSteerStaby</code> (Vehicle Steering Stability): Fahrdynamische Stabilisierungseingriffe.\n</li><li><code>DrvrAsscSteer</code> (Driver Assistance Steering): ADAS/AD-Spurführungs- und Lenkassistenzfunktionen.\n</li></ul>\n</li><li><strong>Domänenübergreifende Partner-SW-Cs (<code>Other SW-C</code>):</strong>\n<ul class=\"fig-list\"><li><code>Hmi</code> (Fahrerschnittstelle / Drive Mode Selection / Warnungen).\n</li><li><code>Esc</code> (Electronic Stability Control: Raddrehzahlen, Gierraten, Giermomentanforderungen).\n</li><li><code>CrsCtlAndAcc</code> (Cruise Control &amp; Adaptive Cruise Control).\n</li><li><code>Susp</code> (Aktive/Adaptive Federungs- und Dämpfungssysteme).\n</li></ul>\n</li><li><strong>Kern-Lenkungs-SW-C (<code>Steer</code> – Composition):</strong>\n<ul class=\"fig-list\"><li><code>High-level steering arbitration and coordination (SAC)</code>: Zentrale Schiedsinstanz für externe Winkel- und Momentenanforderungen; priorisiert Anforderungen von Fahrer, Assistenzsystemen und Fahrdynamikregelung.\n</li><li><code>VGR</code> (Variable Gear Ratio): Geschwindigkeits- und fahrdynamikabhängige variable Lenkübersetzung.\n</li><li><code>RPRA</code> (Road-Pinion-Road-Angle Transformation): Kinematische bidirektionale Transformation zwischen Ritzelwinkel (<em>pinion angle</em>) und Radlenkwinkel (<em>road wheel angle</em>).\n</li><li><code>Basic Rear Wheel Steering (BRWS)</code>: Hinterachslenkungs-Teilsystem.\n</li><li><code>Basic Steer Angle Superposition (BSAS)</code>: Vorderachs-Winkelüberlagerungs-Teilsystem (z. B. AFS – Active Front Steering).\n</li><li><code>Basic Steer Torque Superposition (BSTS)</code>: Momentenüberlagerung und Basiskraftunterstützung (z. B. EPS – Electric Power Steering).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Interne, nicht standardisierte Funktionsblöcke (White-Box / Tier-1-IP)</h5>\n<ul class=\"fig-list\"><li>Innerhalb <code>VGR</code>: <code>VGR</code>-Kennlinien/Kerne, <code>Lead / Lag</code>-Filterglieder.\n</li><li>Innerhalb <code>RPRA</code>: <code>Road wheel angle arbitration</code>, <code>Road to pinion angle</code>, <code>Pinion to road angle</code>.\n</li><li>Innerhalb <code>BRWS</code>: <code>Low-level steering position arbitration</code>, <code>BRWS actuator control</code>.\n</li><li>Innerhalb <code>BSAS</code>: <code>Low-level steering position coordination</code>, <code>BSAS actuator control</code>.\n</li><li>Innerhalb <code>BSTS</code>: Basiskompensatoren (<code>Damping</code>, <code>Returnability</code>, <code>Inertia comp</code>), Basisfunktionen (<code>Assist</code>, <code>Pulse Generator</code>), <code>Low-level driver torque arbitration</code>, <code>BSTS actuator control</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen &amp; Beziehungen</h5>\n<ul class=\"fig-list\"><li><strong>Kommunikationsmuster:</strong> Sender-Receiver-Kommunikation (<code>SenderReceiverInterface</code>) über VFB/RTE.\n</li><li><strong>Kardinalitäten:</strong> 1:n-Signalverteilung für Referenzgrößen (z. B. Radlenkwinkel von <code>RPRA</code> an <code>Esc</code>, <code>SAC</code> und <code>Susp</code>); n:1-Arbitrierungsknotenpunkte in <code>SAC</code>, <code>RPRA</code> und <code>BSTS</code>.\n</li><li><strong>Kopplungen:</strong>\n<ul class=\"fig-list\"><li>Externe Ports: <code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>, <code>Hmi</code>, <code>Esc</code>, <code>CrsCtlAndAcc</code>, <code>Susp</code> interagieren direkt über VFB-Ports mit <code>SAC</code> bzw. der äußeren Boundary der <code>Steer</code>-Composition.\n</li><li>Interne Signalflüsse: <code>SAC</code> steuert <code>BRWS</code>, <code>VGR</code> und <code>BSTS</code> an. <code>VGR</code> und <code>RPRA</code> sind bidirektional gekoppelt. <code>RPRA</code> liefert transformierte Soll-/Istgrößen an <code>BSAS</code>, <code>BSTS</code> und zurück an <code>SAC</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Sollwert-Erfassung &amp; Vorkonditionierung (Asynchron / Periodisch):</strong>\n<ul class=\"fig-list\"><li>Externe SW-Cs (<code>VehSteerStaby</code>, <code>DrvrAsscSteer</code>) und Fahrerwunsch-Erfassung (<code>Hmi</code>, Lenkmomentsensor) übergeben zyklisch Soll-Winkel bzw. Soll-Momente an die R-Ports von <code>SAC</code>.\n</li></ul>\n</li><li><strong>High-Level-Arbitrierung (<code>SAC</code>):</strong>\n<ul class=\"fig-list\"><li>Bewertung der Integrität, Betriebsmodi und Prioritäten (Fahrdynamikstabilisierung &gt; Notausweich-Assistenz &gt; Komfort-Assistenz).\n</li><li>Verteilung der arbitrierten Führungsgrößen: Winkelanforderungen an <code>VGR</code>/<code>RPRA</code>, Momentenanforderungen an <code>BSTS</code>, Hinterachswinkel an <code>BRWS</code>.\n</li></ul>\n</li><li><strong>Kinematische Transformation &amp; Vorfilterung (<code>VGR</code>, <code>RPRA</code>):</strong>\n<ul class=\"fig-list\"><li>Berechnung der dynamischen Übersetzung via <code>VGR</code> unter Einbeziehung von Fahrzeugzustandsgrößen (z. B. Fahrzeuggeschwindigkeit via Bus).\n</li><li>Transformation durch <code>RPRA</code>: Umrechnung des resultierenden Soll-Ritzelwinkels in Radlenkwinkel (und umgekehrt für Istwert-Rückmeldungen z. B. an <code>Esc</code>).\n</li></ul>\n</li><li><strong>Low-Level-Arbitrierung &amp; Überlagerung (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS</code>):</strong>\n<ul class=\"fig-list\"><li>Lokale Arbitrierung gegen physikalische Aktuatorgrenzen (Endanschlagsschutz, thermische Deratings, Gradientenbegrenzungen).\n</li><li>In <code>BSTS</code>: Überlagerung von Handmoment, Lenkunterstützung (<code>Assist</code>), Dämpfung (<code>Damping</code>), Rückstellung (<code>Returnability</code>) und Trägheitskompensation (<code>Inertia comp</code>).\n</li></ul>\n</li><li><strong>Aktuator-Ansteuerung &amp; Feedback (Synchrone Reglerschleife):</strong>\n<ul class=\"fig-list\"><li>Ausgabe der finalen Stellsignale an die Aktuatorregler (<code>* actuator control</code>).\n</li><li>Istwert-Rückführung über Sensor-SW-Cs / Hardware-Abstraction-Layer (IoHwAb) zurück in die Reglerkreise (<code>RPRA</code> → <code>SAC</code> → <code>Esc</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standardisierungs-Scope (<code>AUTOSAR_EXP_AIChassis</code>):</strong>\n<ul class=\"fig-list\"><li><em>Normativ / Standardisiert:</em> Die Ports, Datentypen und Interfaces an der Außenhülle der SW-Cs (Dunkelblau/Grün/Grau) zur Gewährleistung der Portabilität von ADAS/Chassis-Funktionen zwischen verschiedenen OEM-Plattformen.\n</li><li><em>Nicht standardisiert (Proprietär):</em> Alle hellgrün hinterlegten Funktionsblöcke. Die mathematischen Modelle für Dynamikkompensation, Filterung (<code>Lead/Lag</code>) und Aktuatorregler verbleiben als geistiges Eigentum (IP) des Tier-1/Zulieferers.\n</li></ul>\n</li><li><strong>RTE- und Task-Design:</strong>\n<ul class=\"fig-list\"><li><code>SAC</code>, <code>VGR</code> und <code>RPRA</code> laufen typischerweise in schnellen periodischen Chassis-Tasks (t_cycle = 5\\,ms … 10\\,ms).\n</li><li>Aktuatornahe Regelkreise (<code>BSAS</code>, <code>BRWS</code>, <code>BSTS actuator control</code>) erfordern harte Echtzeit-Ausführung (t_cycle ≤ 1\\,ms … 2\\,ms), häufig ausgelagert auf dedizierte Motor-Control-Cores oder komplexe Treiber (CDD) bei mechatronischen EPS-Systemen.\n</li></ul>\n</li><li><strong>Signalintegrität &amp; ASIL-Allokation:</strong>\n<ul class=\"fig-list\"><li>Lenkeingriffe via <code>DrvrAsscSteer</code> und <code>VehSteerStaby</code> erfordern funktionale Sicherheit bis ASIL D (ISO 26262). Schnittstellen müssen End-to-End-Protection (E2E-Profile: CRC, Alive-Counter, Data-ID) aufweisen.\n</li><li><code>SAC</code> und <code>Low-level driver torque arbitration</code> müssen Plausibilisierungs- und Degradationsstrategien (Safe State) implementieren, falls Geberwerte ausfallen oder Signalinkonsistenzen zwischen <code>RPRA</code> und externen Sensordaten (<code>Esc</code>) auftreten.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-37c6c5fc9b7bc10f", "to": "FIG-c73af67f5ddf6043", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bildbeschriftung oben links: Hinzufügen des Textes „Figure 14.“ oberhalb des Legendenkastens.\n</li></ul>"}, {"from": "FIG-c73af67f5ddf6043", "to": "FIG-628d70dbcd1152a8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-628d70dbcd1152a8", "to": "FIG-ce6167db30a6a08b", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ce6167db30a6a08b", "to": "FIG-cc1fe776cb87f790", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cc1fe776cb87f790", "to": "FIG-2f0f777aaed749c6", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Bildbeschriftung oben links: Entfernen des Textes „Figure 14.“ oberhalb des Legendenkastens.\n</li></ul>"}, {"from": "FIG-2f0f777aaed749c6", "to": "FIG-8f3cb66c199fc31a", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
